  name: "data",
  numberType: "f64",
  types: {
    date: scalar("f64", { note: "milliseconds since 1970-01-01, UTC" }),
  },
  spaces: { row: { pure: true }, group: { pure: true }, scalar: { pure: true } },
  objects: {
    Params: { label: "the params ($)", members: {} },
  },
