files.examples/07.js:
// REFUSED: B009 ".fragment" is rejected: "fragments are not part of this language" (and column attributes
// unit/currency have no home). The fragment bodies winsorize and zscore are written out by hand below;
// quantiles and stats come from the derive lambda's second parameter.
import { program } from "../data.grammar.js";

export default program("outliers")
  .source("sales", { csv: "data/sales.csv", columns: { date: "date", region: "str", units: "f64", price: "f64" } })
  .table("clean", "sales")
  .derive("price", (row, s) => max(min(row.price, s.quantile("price", 0.99)), s.quantile("price", 0.01)))
  .derive("price_z", (row, s) => (row.price - s.mean("price")) / s.sd("price"))
  .chart("dist", "clean", "histogram")
  .x("price_z")
  .rule(3, { label: "3σ" });

files.examples/08.js:
// REFUSED: no code. built.ir, listing(), lineage(), downstreamOf(), diff() and toJSON() read the built
// Program, not the builder; the Definition API has no output side for them. The checker has no
// diagnostic for a missing feature. Only the Program of example 4 (which this example builds) is below.
import { program } from "../data.grammar.js";

export default program("revenue-by-month")
  .source("sales", { csv: "data/sales.csv", columns: { date: "date", region: "str", units: "f64", price: "f64" } })
  .param("metric", { options: ["revenue", "units"], value: "revenue" })
  .table("monthly", "sales")
  .derive("revenue", row => row.units * row.price)
  .derive("month", row => truncMonth(row.date))
  .groupBy("month", "region")
  .agg({
    revenue: g => g.sum("revenue"),
    units: g => g.sum("units"),
    orders: g => g.count(),
  })
  .sort("month")
  .table("monthly_pos", "monthly")
  .filter(r => r.units > 0)
  .chart("trend", "monthly_pos", "line")
  .x("month", { type: "time" })
  .yBy(() => $.metric)
  .color("region");

files.examples/09.js:
// REFUSED: no code. The Environment, session, event log, undo and permissions (s.set, s.addStep, s.log,
// env.commit) are not Program builder calls; nothing in the API defines them. The Program a session would
// end with (the refund table and chart, as written in the example) is below.
import { program } from "../data.grammar.js";

export default program("sales-env")
  .source("sales_raw", { csv: "data/sales.csv", columns: { date: "date", region: "str", units: "f64", price: "f64" } })
  .param("minUnits", { min: 0, max: 500, step: 10, value: 50 })
  .table("sales", "sales_raw")
  .filter(row => row.price > 0)
  .table("refunds", "sales_raw")
  .filter(row => row.price < 0)
  .groupBy("region")
  .agg({ n: g => g.count() })
  .chart("refundBars", "refunds", "bar")
  .x("region")
  .y("n");
